import 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:firebase_auth/firebase_auth.dart';\nimport '../services/auth_service.dart';\nimport '../services/user_service.dart';\nimport '../models/user_model.dart';\n\nfinal authServiceProvider = Provider((ref) => AuthService());\nfinal userServiceProvider = Provider((ref) => UserService());\n\nfinal authStateProvider = StreamProvider<AuthState>((ref) {\n  final authService = ref.watch(authServiceProvider);\n  return authService.authStateChanges().map((user) {\n    if (user == null) {\n      return const AuthState.unauthenticated();\n    }\n    return AuthState.authenticated(user);\n  });\n});\n\nfinal currentUserProvider = StreamProvider<UserModel?>((ref) {\n  final authState = ref.watch(authStateProvider);\n  final userService = ref.watch(userServiceProvider);\n\n  return authState.when(\n    loading: () => Stream.value(null),\n    data: (state) {\n      return state.when(\n        authenticated: (user) => userService.getUserStream(user.uid),\n        unauthenticated: () => Stream.value(null),\n        error: (_) => Stream.value(null),\n      );\n    },\n    error: (_, __) => Stream.value(null),\n  );\n});\n\nfinal loginProvider = FutureProvider.family<void, (String, String)>(\n  (ref, credentials) async {\n    final authService = ref.watch(authServiceProvider);\n    await authService.loginWithEmail(credentials.$1, credentials.$2);\n  },\n);\n\nfinal registerProvider = FutureProvider.family<void, (String, String)>(\n  (ref, credentials) async {\n    final authService = ref.watch(authServiceProvider);\n    final userService = ref.watch(userServiceProvider);\n    \n    final userCredential = await authService.registerWithEmail(credentials.$1, credentials.$2);\n    \n    final user = UserModel(\n      id: userCredential.user!.uid,\n      email: credentials.$1,\n      createdAt: DateTime.now(),\n      updatedAt: DateTime.now(),\n    );\n    \n    await userService.createUser(user);\n  },\n);\n\nfinal googleLoginProvider = FutureProvider<void>((ref) async {\n  final authService = ref.watch(authServiceProvider);\n  final userService = ref.watch(userServiceProvider);\n  \n  final userCredential = await authService.loginWithGoogle();\n  \n  if (userCredential != null && userCredential.user != null) {\n    final existingUser = await userService.getUser(userCredential.user!.uid);\n    \n    if (existingUser == null) {\n      final user = UserModel(\n        id: userCredential.user!.uid,\n        email: userCredential.user!.email ?? '',\n        fullName: userCredential.user!.displayName,\n        photoUrl: userCredential.user!.photoURL,\n        createdAt: DateTime.now(),\n        updatedAt: DateTime.now(),\n      );\n      await userService.createUser(user);\n    }\n  }\n});\n\nfinal logoutProvider = FutureProvider<void>((ref) async {\n  final authService = ref.watch(authServiceProvider);\n  await authService.logout();\n});\n\nsealed class AuthState {\n  const AuthState();\n  \n  const factory AuthState.loading() = _Loading;\n  const factory AuthState.authenticated(User user) = _Authenticated;\n  const factory AuthState.unauthenticated() = _Unauthenticated;\n  const factory AuthState.error(String message) = _Error;\n  \n  T when<T>({\n    required T Function() loading,\n    required T Function(User user) authenticated,\n    required T Function() unauthenticated,\n    required T Function(String message) error,\n  }) {\n    return switch (this) {\n      _Loading() => loading(),\n      _Authenticated(user: var user) => authenticated(user),\n      _Unauthenticated() => unauthenticated(),\n      _Error(message: var message) => error(message),\n    };\n  }\n}\n\nclass _Loading extends AuthState {\n  const _Loading();\n}\n\nclass _Authenticated extends AuthState {\n  final User user;\n  const _Authenticated(this.user);\n}\n\nclass _Unauthenticated extends AuthState {\n  const _Unauthenticated();\n}\n\nclass _Error extends AuthState {\n  final String message;\n  const _Error(this.message);\n}\n